function e(t){return t==null?"—":"$ "+Number(t).toLocaleString("es-AR",{minimumFractionDigits:2})}function o(t){const n=Number(t)||0,i=Math.abs(n),r=n<0?"-":"";return i>=1e6?r+"$ "+(i/1e6).toLocaleString("es-AR",{maximumFractionDigits:1})+"M":i>=1e3?r+"$ "+(i/1e3).toLocaleString("es-AR",{maximumFractionDigits:1})+"k":r+"$ "+i.toLocaleString("es-AR",{maximumFractionDigits:0})}function a(t){return t?new Date(t).toLocaleDateString("es-AR",{day:"2-digit",month:"2-digit",year:"numeric"}):"—"}function u(t){return t?new Date(t).toLocaleString("es-AR",{timeZone:"America/Argentina/Buenos_Aires",day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:!1}):"—"}export{o as a,a as b,u as c,e as f};
